#!/bin/bash
sed -i 's/    LaunchedEffect(viewMode) {/    val pageOrder = remember { listOf(ViewMode.LIST, ViewMode.READING, ViewMode.TAFSIR, ViewMode.MUSHAF) }\n    val pagerState = androidx.compose.foundation.pager.rememberPagerState(\n        initialPage = pageOrder.indexOf(parsedViewMode).takeIf { it >= 0 } ?: 0,\n        pageCount = { 4 }\n    )\n\n    LaunchedEffect(pagerState.targetPage) {\n        val newMode = pageOrder[pagerState.targetPage]\n        if (viewMode != newMode) {\n            if (newMode == ViewMode.TAFSIR \&\& viewMode != ViewMode.TAFSIR) {\n                isTafsirSwitching = true\n            } else {\n                isTafsirSwitching = false\n            }\n            viewMode = newMode\n        }\n    }\n\n    LaunchedEffect(viewMode) {/g' app/src/main/java/com/example/ui/screens/SurahDetailScreen.kt
